ted);text-align:center;font-size:.72rem}.ef-link{color:#fff;font-weight:850;text-decoration:none}@keyframes efRise{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:translateY(0)}}@media(max-width:430px){body{background:#101827}.ef-page{display:block;min-height:100dvh;padding:0}.ef-shell{width:100%;height:100dvh;min-height:100dvh;padding:76px 22px calc(34px + env(safe-area-inset-bottom));border-radius:0;box-shadow:none}.ef-shell::before{inset:0;border-radius:0}.ef-shell::after{display:none}.ef-back{top:22px}.ef-brand{top:28px;right:22px}.ef-card{padding:24px 20px 21px;border-radius:26px}.ef-title{font-size:1.76rem}}@media(prefers-reduced-motion:reduce){.ef-card{animation:none}}
.ef-send-otp{margin-left:auto;color:#fff;font-size:.64rem;font-weight:850;border:1px solid rgba(255,255,255,.22);border-radius:999px;background:rgba(255,255,255,.12);padding:6px 9px;white-space:nowrap;cursor:pointer}.ef-otp-badge{display:none;width:max-content;margin:5px 0 0 auto;padding:4px 8px;border-radius:999px;color:#DCFCE7;background:rgba(22,101,52,.26);border:1px solid rgba(134,239,172,.35);font-size:.6rem;font-weight:850}.ef-otp-badge.is-visible{display:block}.ef-otp{display:none}.ef-otp.is-visible{display:block}</style><script>window.SD_AUTH={otpUrl:<?= json_encode(site_url('sd-send-otp')) ?>,csrfName:<?= json_encode(csrf_token()) ?>,csrfHash:<?= json_encode(csrf_hash()) ?>};</script>
