digits(){return phone?phone.value.replace(/\D/g,'').slice(0,10):''}function showOtp(){if(section)section.classList.add('is-visible');if(badge)badge.classList.add('is-visible');if(send)send.textContent='Resend OTP'}if(phone)phone.addEventListener('input',function(){phone.value=digits();if(phone.value.length===10)showOtp()});if(send)send.addEventListener('click',function(){if(digits().length!==10){phone&&phone.focus();return}showOtp();var cfg=window.SD_AUTH||{},body=new URLSearchParams();body.append('phone',digits());if(cfg.csrfName&&cfg.csrfHash)body.append(cfg.csrfName,cfg.csrfHash);if(cfg.otpUrl)fetch(cfg.otpUrl,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded','X-Requested-With':'XMLHttpRequest'},body:body.toString()}).then(function(r){return r.json()}).then(function(data){if(data&&data.csrfHash){cfg.csrfHash=data.csrfHash;window.SD_AUTH=cfg}}).catch(function(){});if(boxes[0])boxes[0].focus()});boxes.forEach(function(box,i){box.addEventListener('input',function(){box.value=box.value.replace(/\D/g,'').slice(0,1);sync();if(box.value&&boxes[i+1])boxes[i+1].focus()});box.addEventListener('keydown',function(e){if(e.key==='Backspace'&&!box.value&&boxes[i-1])boxes[i-1].focus()})})});</script>
